--
-- Structure de la table `fait_ventes`
--

DROP TABLE IF EXISTS `fait_ventes`;
CREATE TABLE IF NOT EXISTS `fait_ventes` (
  `vente_key` bigint(20) NOT NULL AUTO_INCREMENT,
  `code_vente` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `date_key` int(11) NOT NULL,
  `client_key` int(11) NOT NULL,
  `produit_key` int(11) NOT NULL,
  `magasin_key` int(11) NOT NULL,
  `quantite` decimal(12,2) NOT NULL,
  `prix_unitaire` decimal(12,2) NOT NULL,
  `montant_vente` decimal(14,2) NOT NULL,
  `devise` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `statut` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`vente_key`),
  UNIQUE KEY `code_vente` (`code_vente`),
  KEY `fk_fv_temps` (`date_key`),
  KEY `fk_fv_client` (`client_key`),
  KEY `fk_fv_produit` (`produit_key`),
  KEY `fk_fv_magasin` (`magasin_key`)
) ENGINE=MyISAM AUTO_INCREMENT=967 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

