--
-- Structure de la table `stg_ventes`
--

DROP TABLE IF EXISTS `stg_ventes`;
CREATE TABLE IF NOT EXISTS `stg_ventes` (
  `code_vente` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `date_vente` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `code_client` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `code_produit` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `code_magasin` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `quantite` decimal(12,2) DEFAULT NULL,
  `prix_unitaire` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `devise` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `statut` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

